#!/usr/bin/env bash
mkdir -p .github
echo '' | base64 -d > .github/v16-live.rs
echo '' | base64 -d > .github/v16-own.diff
echo 'aW1wb3J0IHN5cwpwYXRoLCBvbGQsIG5ldyA9IHN5cy5hcmd2WzFdLCBzeXMuYXJndlsyXSwgc3lzLmFyZ3ZbM10KcyA9IG9wZW4ocGF0aCkucmVhZCgpCm4gPSBzLmNvdW50KG9sZCkKaWYgbiAhPSAxOgogICAgcHJpbnQoZiJNVVRBVElPTiBBTkNIT1IgQ09VTlQge259ICE9IDEiKTsgc3lzLmV4aXQoMykKb3BlbihwYXRoLCAidyIpLndyaXRlKHMucmVwbGFjZShvbGQsIG5ldykpCg==' | base64 -d > .github/v16-mutate.py
set -u; mkdir -p ci-logs
run(){ n=$1; shift; echo "+ $*" | tee ci-logs/$n.log; "$@" 2>&1 | tee -a ci-logs/$n.log; rc=${PIPESTATUS[0]}; echo "EXIT_CODE=$rc" | tee -a ci-logs/$n.log; echo "$n exit=$rc" >> ci-logs/exits.txt; }
M=src-tauri/Cargo.toml
D=src-tauri/src/ssh/direct.rs
T=src-tauri/src/ssh/direct_tests.rs
git rev-parse HEAD HEAD^{tree} > ci-logs/commit.txt; rustc -V >> ci-logs/commit.txt; ssh -V 2>> ci-logs/commit.txt; echo "XDG_RUNTIME_DIR=${XDG_RUNTIME_DIR:-unset} uid=$(id -u)" >> ci-logs/commit.txt
sha1sum $D $T src-tauri/src/ssh/host_key.rs >> ci-logs/commit.txt
# live tests appended to the test module (scratch)
cat .github/v16-live.rs >> $T
cp $T /tmp/direct_tests_live.rs

# ---------- live sshd ----------
V=$(mktemp -d /tmp/v16.XXXX); chmod 700 $V; PORT=22916; U=$(id -un)
ssh-keygen -q -t ed25519 -N '' -f $V/host; ssh-keygen -q -t ed25519 -N '' -f $V/key; ssh-keygen -q -t ed25519 -N '' -f $V/key2
cp $V/key.pub $V/ak
printf 'Port %s\nListenAddress 127.0.0.1\nHostKey %s/host\nPidFile none\nUsePAM no\nStrictModes no\nAuthorizedKeysFile %s/ak\nPasswordAuthentication no\nKbdInteractiveAuthentication no\nLogLevel VERBOSE\nMaxStartups 100\nMaxSessions 50\n' $PORT $V $V > $V/sshd_config
mkdir -p ~/.ssh; chmod 700 ~/.ssh; echo "[127.0.0.1]:$PORT $(cut -d' ' -f1,2 $V/host.pub)" >> ~/.ssh/known_hosts
ls ~/.ssh/ > ci-logs/home-ssh.txt
/usr/sbin/sshd -D -f $V/sshd_config -E $V/sshd.log & SSHD=$!
for i in $(seq 50); do (exec 3<>/dev/tcp/127.0.0.1/$PORT) 2>/dev/null && break; sleep 0.1; done
export V16_PORT=$PORT V16_USER=$U V16_KEY=$V/key V16_KEY2=$V/key2 V16_DIR=$V V16_SSHD_LOG=$V/sshd.log
ssh -o BatchMode=yes -i $V/key -p $PORT $U@127.0.0.1 echo sshd-sanity > ci-logs/sshd-sanity.log 2>&1; echo "sanity rc=$?" >> ci-logs/sshd-sanity.log

UIDN=$(id -u); CM=/tmp/ferryx-cm-$UIDN
sudo useradd -M -s /usr/sbin/nologin v16evil || true
live(){ tag=$1; shift; run live-$tag-$1 cargo test --manifest-path $M --lib -- --ignored --exact --nocapture --test-threads=1 "ssh::direct::tests::$1"; }
hijack(){ tag=$1; for mode in none dir dir0700 symlink; do
  sudo rm -rf $CM /tmp/v16-attacker
  case $mode in
    dir) sudo mkdir -m 0777 $CM; sudo chown v16evil:v16evil $CM; export V16_ATTACK_DIR=$CM;;
    dir0700) sudo mkdir -m 0700 $CM; sudo chown v16evil:v16evil $CM; sudo chmod 0711 $CM; export V16_ATTACK_DIR=/nonexistent;;
    symlink) sudo mkdir -m 0777 /tmp/v16-attacker; sudo chown v16evil:v16evil /tmp/v16-attacker; sudo -u v16evil ln -s /tmp/v16-attacker $CM; export V16_ATTACK_DIR=/tmp/v16-attacker;;
    none) export V16_ATTACK_DIR=/nonexistent;;
  esac
  ls -ld $CM /tmp/v16-attacker > ci-logs/hijack-$tag-$mode-setup.txt 2>&1
  V16_HIJACK=$mode run live-$tag-hijack-$mode cargo test --manifest-path $M --lib -- --ignored --exact --nocapture --test-threads=1 ssh::direct::tests::v16_live_hijack_socket_dir
  sudo ls -la $CM/ /tmp/v16-attacker/ >> ci-logs/hijack-$tag-$mode-setup.txt 2>&1
done; sudo rm -rf $CM /tmp/v16-attacker; }

# ---------- LANE unit suites ----------
for f in ssh:: ipc::ssh terminal::remote; do n=$(echo $f | tr -c 'a-z\n' _); run test-lane-$n cargo test --manifest-path $M --lib "$f" -- --test-threads=2; done
# ---------- LANE live ----------
for t in v16_live_reuse_authenticates_once v16_live_bind_failure_runs_command_exactly_once v16_live_remote_exit_255_is_not_retried v16_live_forged_bind_text_from_remote_is_not_retried v16_live_user_change_does_not_ride_master v16_live_key_change_does_not_ride_master; do live lane $t; done
hijack lane
# raw OpenSSH facts used by the review
{ echo "== %C inputs"; for a in "-p 1 a@h" "-p 1 b@h" "-p 1 -i /x a@h" "-p 1 -i /y a@h" "-p 2 a@h" "-p 1 -J j@k a@h"; do echo "$a -> $(ssh -G -F /dev/null -o ControlPath=/c/%C $a 2>/dev/null | grep -i '^controlpath')"; done; } > ci-logs/percent-C.txt
# ---------- MUTATIONS ----------
mut(){ name=$1; old=$2; new=$3; shift 3; cp $D /tmp/direct.orig
  if ! python3 .github/v16-mutate.py $D "$old" "$new"; then echo "mut-$name APPLY-FAILED" >> ci-logs/exits.txt; return; fi
  diff /tmp/direct.orig $D > ci-logs/mut-$name.diff
  run mut-$name-unit cargo test --manifest-path $M --lib ssh::direct -- --test-threads=2
  for t in "$@"; do if [ "$t" = hijack ]; then hijack mut-$name; else live mut-$name $t; fi; done
  cp /tmp/direct.orig $D; }
mut M1-no-owner-mode-check 'if !meta.is_dir() || meta.uid() != uid || meta.mode() & 0o777 != 0o700 {' 'if !meta.is_dir() && uid == uid {' hijack
mut M2-no-host-id-hash 'format!("{dir}/{}-%C", &digest[..CONTROL_HOST_DIGEST_LEN])' 'format!("{dir}/{}%C", &digest[..0])'
mut M3-retry-any-255 '.is_some_and(|stderr| stderr.contains("unix_listener: cannot bind"))' '.is_some_and(|_| error.details.as_ref().is_some_and(|d| d["exitCode"] == 255))' v16_live_remote_exit_255_is_not_retried
git diff --stat > ci-logs/after-mutations-status.txt
kill $SSHD; grep -c "Accepted publickey" $V/sshd.log > ci-logs/sshd-accepted-total.txt; cp $V/sshd.log ci-logs/sshd.log
# ---------- CLIPPY lane vs stacking base ----------
git checkout -- $T
clip(){ tag=$1; run clippy-$tag cargo clippy --manifest-path $M --all-targets --message-format=short; sed 's/\x1b\[[0-9;]*m//g' ci-logs/clippy-$tag.log | grep -E '^src/.*(error|warning):' | sed -E 's/:[0-9]+:[0-9]+:/:/' | sort | uniq -c > ci-logs/clippy-$tag-norm.txt; }
clip lane
run base-revert git apply -R .github/v16-own.diff
clip base
diff ci-logs/clippy-base-norm.txt ci-logs/clippy-lane-norm.txt > ci-logs/clippy-lane-vs-base.diff; echo "clippy-diff exit=$?" >> ci-logs/exits.txt
git apply .github/v16-own.diff; git status --short > ci-logs/final-status.txt
cat ci-logs/exits.txt
